CREATE TABLE users (id TEXT PRIMARY KEY, google_sub TEXT UNIQUE NOT NULL, email TEXT NOT NULL, name TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'USER' CHECK(role IN ('USER','ADMIN')), status TEXT NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','APPROVED','REJECTED','SUSPENDED')), company_type TEXT, job_role TEXT, career_years TEXT, ai_level TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, approved_at TEXT, approved_by TEXT, last_login_at TEXT);
CREATE TABLE sessions (id_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), expires_at TEXT NOT NULL, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE oauth_states (state_hash TEXT PRIMARY KEY, verifier TEXT NOT NULL, expires_at TEXT NOT NULL);
CREATE TABLE weeks (id INTEGER PRIMARY KEY, title TEXT NOT NULL, objective TEXT NOT NULL, why_text TEXT NOT NULL, follow_steps TEXT NOT NULL, tool_types TEXT NOT NULL DEFAULT '[]', updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE lessons (id TEXT PRIMARY KEY, week_id INTEGER NOT NULL REFERENCES weeks(id), title TEXT NOT NULL, body TEXT NOT NULL, sort_order INTEGER NOT NULL DEFAULT 0, created_at TEXT DEFAULT CURRENT_TIMESTAMP, updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE resources (id TEXT PRIMARY KEY, week_id INTEGER REFERENCES weeks(id), guide_tool TEXT, title TEXT NOT NULL, description TEXT DEFAULT '', resource_type TEXT NOT NULL CHECK(resource_type IN ('TEXT','YOUTUBE','EXTERNAL_URL','VIDEO_FILE','PDF','IMAGE')), tool_type TEXT NOT NULL DEFAULT 'GENERAL', url TEXT, file_id TEXT, source TEXT, is_required INTEGER NOT NULL DEFAULT 0, sort_order INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'CURRENT' CHECK(status IN ('CURRENT','CHECK_REQUIRED','OUTDATED','HIDDEN')), last_verified_at TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP, updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE assignments (id TEXT PRIMARY KEY, week_id INTEGER NOT NULL REFERENCES weeks(id), title TEXT NOT NULL, description TEXT NOT NULL, instructions TEXT NOT NULL, evaluation_mode TEXT NOT NULL DEFAULT 'AI' CHECK(evaluation_mode IN ('AI','HUMAN','HYBRID')), pass_score INTEGER NOT NULL DEFAULT 80, max_attempts INTEGER NOT NULL DEFAULT 0, required_submission_types TEXT NOT NULL DEFAULT '["TEXT"]', ai_prompt TEXT DEFAULT '', is_required INTEGER NOT NULL DEFAULT 1, always_review INTEGER NOT NULL DEFAULT 0, sort_order INTEGER NOT NULL DEFAULT 0, updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE assignment_rubrics (id TEXT PRIMARY KEY, assignment_id TEXT NOT NULL REFERENCES assignments(id), name TEXT NOT NULL, description TEXT NOT NULL, max_score INTEGER NOT NULL, sort_order INTEGER NOT NULL DEFAULT 0);
CREATE TABLE submissions (id TEXT PRIMARY KEY, assignment_id TEXT NOT NULL REFERENCES assignments(id), user_id TEXT NOT NULL REFERENCES users(id), attempt_number INTEGER NOT NULL, text_content TEXT DEFAULT '', submitted_url TEXT, status TEXT NOT NULL DEFAULT 'SUBMITTED', review_reason TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP, UNIQUE(assignment_id,user_id,attempt_number));
CREATE TABLE files (id TEXT PRIMARY KEY, owner_type TEXT NOT NULL, owner_id TEXT NOT NULL, r2_key TEXT NOT NULL UNIQUE, original_filename TEXT NOT NULL, mime_type TEXT NOT NULL, size INTEGER NOT NULL, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE submission_files (submission_id TEXT NOT NULL REFERENCES submissions(id), file_id TEXT NOT NULL REFERENCES files(id), PRIMARY KEY(submission_id,file_id));
CREATE TABLE evaluations (id TEXT PRIMARY KEY, submission_id TEXT NOT NULL REFERENCES submissions(id), evaluator_type TEXT NOT NULL CHECK(evaluator_type IN ('AI','ADMIN')), score INTEGER, result TEXT NOT NULL CHECK(result IN ('PASS','RETRY','HUMAN_REVIEW_REQUIRED')), confidence REAL, feedback_json TEXT NOT NULL, model_id TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP, reviewed_by TEXT);
CREATE TABLE user_week_progress (user_id TEXT NOT NULL REFERENCES users(id), week_id INTEGER NOT NULL REFERENCES weeks(id), status TEXT NOT NULL, manually_unlocked INTEGER NOT NULL DEFAULT 0, completed_at TEXT, updated_at TEXT DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(user_id,week_id));
CREATE TABLE app_settings (key TEXT PRIMARY KEY, value TEXT NOT NULL, updated_at TEXT DEFAULT CURRENT_TIMESTAMP, updated_by TEXT);
CREATE TABLE audit_logs (id TEXT PRIMARY KEY, actor_id TEXT, action TEXT NOT NULL, target_type TEXT, target_id TEXT, details TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_sessions_user ON sessions(user_id); CREATE INDEX idx_submissions_user ON submissions(user_id,assignment_id); CREATE INDEX idx_submissions_status ON submissions(status,created_at); CREATE INDEX idx_resources_week ON resources(week_id,sort_order); CREATE INDEX idx_audit_created ON audit_logs(created_at);
